Given a string s consisting of lowercase letters, for each position i in the string (0 ≤ i < n), find the first non-repeating character in the prefix s[0..i]. If no such character exists, use '#'.Examples:Input: s = "aabc"Output: a#bbExplanation: After ("a"): First non-repeating character is 'a'.After ("aa"): No non-repeating character, so '#'.After ("a#b"): First non-repeating character is 'b'.After ("aabc"): Non-repeating characters are 'b' and 'c'; 'b' appeared first, so 'b'. Result = a#bbInput: s = "bb"Output: b#Explanation: After ("b"): First non-repeating character is 'b'.After ("bb"): No non-repeating character, so '#'.Result = b#Try It YourselfTable of Content[Naive Approach] Using Nested Loop - O(n2) time and O(n) space[Better Approach] Using Queue and Frequency Array - O(n) Time and O(n) Space[Expected Approach] Using Frequency and Last Occurrence Array- O(n) Time and O(1) Space[Naive Approach] Using Nested Loop - O(n2) time and O(n) spaceThis approach maintains a frequency count of each character using a vector. For each character in the string, it scans from the beginning to find the first non-repeating character by checking the frequency of each character up to that point. If a non-repeating character is found, it is appended to the result; otherwise, # is appended when no such character exists. This process ensures that the first non-repeating character is identified at each step.
            C++

    #include <iostream>
#include <string>
#include <vector>
using namespace std;

string firstNonRepeating(string &s){
    string ans;
    int n = s.size();

    // frequency vector for all ASCII characters
    vector<int> freq(26, 0);

    // Process each character in the stream
    for (int i = 0; i < n; i++){

        // Update frequency for the current character
        freq[s[i]-'a']++;

        // Scan from the beginning to find the first non-repeating character
        bool found = false;

        for (int j = 0; j <= i; j++){
            if (freq[s[j]-'a'] == 1){
                ans.push_back(s[j]);
                found = true;
                break;
            }
        }


        if (!found){
            ans.push_back('#');
        }
    }

    return ans;
}

int main() {
    string s = "aabc";
    string ans = firstNonRepeating(s);
    cout << ans << endl;
    return 0;
}


