[Better Approach] Using Queue and Frequency Array - O(n) Time and O(n) SpaceWe use a count array of size 26 to track character frequencies and a queue to maintain their order of appearance. For each new character, we update its frequency and push it into the queue. Then, we remove characters from the front of the queue until the first non-repeating character is found, or the queue becomes empty.
            C++

    #include <iostream>
#include<queue>
#include<vector>
using namespace std;

string firstNonRepeating(string& s){
    string ans = "";

    vector<int> count(26, 0);

    queue<char> q;

    for (int i = 0; i < s.length(); i++) {

        // if non-repeating element found push it in queue
        if (count[s[i] - 'a'] == 0) {
            q.push(s[i]);
        }
        count[s[i] - 'a']++;

        // if front element is repeating pop it from the queue
        while (!q.empty() && count[q.front() - 'a'] > 1) {
            q.pop();
        }

        // if queue is not empty append front
        // element else append "#" in ans string.
        if (!q.empty()) {
            ans += q.front();
        }
        else {
            ans += '#';
        }
    }

    return ans;
}

int main()
{
    string s = "aabc";
    string ans = firstNonRepeating(s);
    cout << ans << "\n";  
    return 0;
}


